from calendar_store import latest

def render(records, lo, hi, asof):
    if lo >= hi:
        return []
    selected = latest(records, asof)
    intervals = []
    for key, (rev, s, e, v) in selected.items():
        if v is None:
            continue
        cs, ce = max(lo, s), min(hi, e)
        if cs < ce:
            intervals.append((cs, ce, rev, key, v))
    points = {lo, hi}
    for cs, ce, rev, key, v in intervals:
        points.add(cs)
        points.add(ce)
    pts = sorted(points)
    segments = []
    for i in range(len(pts) - 1):
        a, b = pts[i], pts[i + 1]
        if a >= b:
            continue
        best = None
        for cs, ce, rev, key, v in intervals:
            if cs <= a and ce >= b:
                if best is None or rev > best[0] or (rev == best[0] and key < best[1]):
                    best = (rev, key, v)
        if best is not None:
            segments.append([a, b, best[2]])
    merged = []
    for seg in segments:
        if merged and merged[-1][1] == seg[0] and merged[-1][2] == seg[2]:
            merged[-1][1] = seg[1]
        else:
            merged.append(list(seg))
    return merged

def evaluate(records, windows):
    return [render(records, lo, hi, t) for lo, hi, t in windows]
